WITH filtered_customers AS (SELECT * FROM customers WHERE signup_date > '2025-02-07' AND age <= 32), is_active_summary AS (SELECT is_active, city, ROUND(STDDEV(credit_limit), 2) AS stddev_credit_limit, SUM(CASE WHEN city = 'Tokyo' THEN 1 ELSE 0 END) AS tokyo_count FROM filtered_customers GROUP BY is_active, city) SELECT is_active, stddev_credit_limit, tokyo_count FROM is_active_summary WHERE tokyo_count < 68
